// ============================================================
// Extrai o JSON da análise da IA (de forma robusta) e prepara
// o snapshot para salvar na Data Table `clarity_snapshots`
// ============================================================
const raw = $input.first().json;
let text = raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

let analysis = null;
try { analysis = JSON.parse(text); } catch (e) {
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) { try { analysis = JSON.parse(fence[1]); } catch (e2) {} }
  if (!analysis) {
    const m = text.match(/\{[\s\S]*\}/);
    if (m) { try { analysis = JSON.parse(m[0]); } catch (e3) {} }
  }
}
if (!analysis) analysis = {
  resumo_executivo: { nota_geral: null, nivel_urgencia: 'media', sintese: text.slice(0, 1200) || 'Análise indisponível nesta execução.' },
  diagnostico: [], quick_wins: [], investigar_no_clarity: []
};

const data = $('Comparar Tendências').first().json;

return [{ json: {
  snapshotDate: data.snapshotDate,
  projectName: data.projectName,
  frustrationScore: data.overview?.frustrationScore ?? 0,
  analysis,
  metrics: {
    generatedAt: data.generatedAt, snapshotDate: data.snapshotDate, periodDays: data.periodDays,
    overview: data.overview, byUrl: data.byUrl, byDevice: data.byDevice, bySource: data.bySource,
    byTech: data.byTech, alerts: data.alerts, apiStatus: data.apiStatus, trends: data.trends
  }
}}];

// ============================================================
// Renderiza o dashboard CRO/UX (padrão visual Cadastra) com
// seletor de data a partir dos snapshots da Data Table
// ============================================================
const q = $('GET – Relatório CRO').first().json.query ?? {};
const rowsRaw = $input.all().map(i => i.json).filter(r => r && r.snapshotDate && r.metrics);
rowsRaw.sort((a, b) => String(b.snapshotDate).localeCompare(String(a.snapshotDate)));

const dates = [...new Set(rowsRaw.map(r => String(r.snapshotDate)))];
// Padrão: dia anterior (snapshot mais recente antes de hoje); se não houver, o mais recente
const todayStr = new Date().toISOString().slice(0, 10);
const defaultDate = dates.find(d => d < todayStr) || dates[0];
const selDate = (q.date && dates.includes(String(q.date))) ? String(q.date) : defaultDate;
const row = rowsRaw.find(r => String(r.snapshotDate) === selDate);

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parse = v => { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { return null; } };
const fmt  = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR');
const pct  = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR') + '%';
const mmss = s => (s === null || s === undefined) ? '—' : Math.floor(s / 60) + 'm ' + Math.round(s % 60) + 's';

const CSS = `
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
:root{--ox:#FF5C28;--dark:#111827;--gray:#6b7280;--gray-light:#9ca3af;--bg:#f4f4f2;--white:#ffffff;--line:#e5e7eb;--line-soft:#f3f4f6;--green:#059669;--green-bg:#ecfdf5;--green-border:#a7f3d0;--yellow:#d97706;--yellow-bg:#fffbeb;--yellow-border:#fde68a;--red:#dc2626;--red-bg:#fef2f2;--red-border:#fecaca;--purple:#7c3aed;--purple-bg:#f5f3ff;--purple-border:#ddd6fe;--sans:'Plus Jakarta Sans',sans-serif;--mono:'JetBrains Mono',monospace;--r:12px;--r-lg:16px;--shadow:0 1px 3px rgba(0,0,0,.08),0 4px 16px rgba(0,0,0,.06);--shadow-lg:0 4px 24px rgba(0,0,0,.08),0 12px 48px rgba(0,0,0,.06)}
body{font-family:var(--sans);background:var(--bg);color:var(--dark);line-height:1.6;min-height:100vh}
.header{background:var(--white);padding:0 40px;height:56px;display:flex;align-items:center;box-shadow:0 1px 0 var(--line);position:sticky;top:0;z-index:200}
.header-inner{max-width:1100px;margin:0 auto;width:100%;display:flex;align-items:center;gap:12px}
.logo{height:26px}.product-name{font-size:16px;font-weight:800;letter-spacing:-.02em}
.product-name span{color:var(--ox)}
.version-badge{background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;padding:3px 10px;border-radius:999px;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.hero{background:linear-gradient(140deg,#e84e1b 0%,#ff6b3d 100%);padding:40px 40px 88px;position:relative;overflow:hidden}
.hero::after{content:'';position:absolute;bottom:0;left:0;right:0;height:72px;background:linear-gradient(to bottom,transparent,var(--bg))}
.hero-inner{max-width:1100px;margin:0 auto;position:relative;z-index:1;color:#fff}
.hero-eyebrow{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;opacity:.75;margin-bottom:10px}
.hero h1{font-size:clamp(26px,4vw,40px);font-weight:800;letter-spacing:-.03em;line-height:1.1;margin-bottom:12px}
.hero-desc{font-size:15px;max-width:640px;opacity:.9;line-height:1.6;margin-bottom:20px}
.hero-badges{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}
.hero-badge{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.25);color:rgba(255,255,255,.92);padding:4px 12px;border-radius:999px;font-size:11px;font-weight:600}
.date-pick{display:flex;align-items:center;gap:10px}
.date-pick label{font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.8}
.date-pick select{padding:10px 16px;border:none;border-radius:var(--r);font-size:14px;font-weight:700;font-family:var(--sans);color:var(--dark);background:var(--white);cursor:pointer;box-shadow:var(--shadow);outline:none;min-width:180px}
.wrap{max-width:1100px;margin:-48px auto 60px;padding:0 40px;position:relative;z-index:10}
.card{background:var(--white);border-radius:var(--r-lg);box-shadow:var(--shadow-lg);padding:36px 40px;margin-bottom:20px}
.card-title{font-size:20px;font-weight:800;letter-spacing:-.02em;margin-bottom:4px}
.card-sub{color:var(--gray);margin-bottom:24px;font-size:14px;line-height:1.6}
.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:8px}
.kpi{background:var(--line-soft);border:1px solid var(--line);border-radius:var(--r);padding:16px;text-align:center;border-top:3px solid var(--ox)}
.kpi-val{font-size:24px;font-weight:800;letter-spacing:-.04em;color:var(--dark);line-height:1.15;margin-bottom:4px}
.kpi-lbl{font-size:11px;font-weight:700;color:var(--gray);text-transform:uppercase;letter-spacing:.06em}
.kpi-trend{font-size:11px;font-weight:700;display:block;margin-top:2px}
.score-frac{font-size:2em;font-weight:800;letter-spacing:-.04em;line-height:1}
.score-frac.hi{color:var(--green)}.score-frac.mid{color:var(--yellow)}.score-frac.lo{color:var(--red)}
.geo-badge{display:inline-block;font-size:12px;font-weight:700;padding:3px 12px;border-radius:999px;text-transform:uppercase;letter-spacing:.04em}
.geo-badge.poor{background:var(--red-bg);color:var(--red);border:1px solid var(--red-border)}
.geo-badge.fair{background:var(--yellow-bg);color:var(--yellow);border:1px solid var(--yellow-border)}
.geo-badge.good{background:var(--green-bg);color:var(--green);border:1px solid var(--green-border)}
.section{background:var(--white);border:1px solid var(--line);border-radius:var(--r-lg);margin-bottom:16px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.07)}
.section-head{padding:16px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;cursor:pointer;user-select:none}
.section-head:hover{background:var(--line-soft)}.section-title{font-size:14px;font-weight:800;letter-spacing:-.01em}
.chev{color:var(--gray-light);font-size:13px}
.section-body{padding:22px}.section-body.hidden{display:none}
.audit-item{border-left:4px solid var(--line);padding:12px 16px;margin:8px 0;background:var(--line-soft);border-radius:0 var(--r) var(--r) 0}
.audit-item.fail{border-left-color:var(--red)}.audit-item.warning{border-left-color:var(--yellow)}.audit-item.pass{border-left-color:var(--green)}
.audit-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px}
.audit-title{font-size:13px;font-weight:700}
.audit-finding{font-size:13px;color:var(--gray);margin-bottom:4px}
.audit-rec{font-size:12px;color:var(--dark);font-style:italic}
.impact-tag{font-size:10px;font-weight:600;padding:2px 6px;border-radius:3px;text-transform:uppercase;letter-spacing:.04em}
.impact-tag.critical{background:#b91c1c;color:#fff}.impact-tag.serious{background:#ea580c;color:#fff}
.impact-tag.moderate{background:#f59e0b;color:#1f2937}.impact-tag.minor{background:#3b82f6;color:#fff}
.feat-item{display:flex;align-items:flex-start;gap:10px;padding:10px 12px;background:var(--white);border:1px solid var(--line);border-radius:8px;font-size:13px;line-height:1.5;margin-bottom:8px}
.feat-check{width:22px;height:22px;background:var(--ox);border-radius:50%;color:#fff;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;flex-shrink:0;margin-top:1px}
.check-block{background:var(--line-soft);border:1px solid var(--line);border-radius:var(--r);padding:14px 18px;margin-bottom:10px}
.check-head{display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap}
.tool-badge{font-size:10px;font-weight:700;padding:2px 8px;border-radius:4px;text-transform:uppercase;background:var(--purple-bg);color:var(--purple);border:1px solid var(--purple-border)}
.filter-code{font-family:var(--mono);font-size:11px;background:#1e1e2e;color:#a6e3a1;padding:6px 10px;border-radius:6px;white-space:pre-wrap;word-break:break-all;margin:6px 0}
.check-q{font-size:12px;color:var(--purple);font-style:italic}
.infra-alert{background:var(--red-bg);border:2px solid var(--red-border);border-radius:var(--r);padding:18px 22px;margin-top:16px}
.infra-alert-head{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:800;color:#be123c;margin-bottom:8px}
.infra-alert ul{margin-left:18px;font-size:13px;color:#881337}
.infra-alert li{margin-bottom:3px;word-break:break-all}
.tbl-wrap{overflow-x:auto;margin-bottom:18px}
.tbl-title{font-size:13px;font-weight:800;margin:14px 0 8px;letter-spacing:-.01em}
.tbl{width:100%;border-collapse:collapse;font-size:12.5px}
.tbl th{background:var(--line-soft);color:var(--gray);font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:9px 10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
.tbl th.c,.tbl td.c{text-align:center}.tbl th.r,.tbl td.r{text-align:right}
.tbl td{padding:9px 10px;border-bottom:1px solid var(--line-soft);word-break:break-all;max-width:340px}
.tbl tr:hover td{background:var(--line-soft)}
.score-pill{font-weight:800}
.sev-legend{display:flex;flex-wrap:wrap;gap:10px;align-items:center;font-size:11px;color:var(--gray);margin-top:14px}
.footer-note{text-align:center;font-size:11px;color:var(--gray-light);margin:24px 0}
.chart-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px}
.chart-box{background:var(--line-soft);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.chart-title{font-size:11px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:var(--gray);margin-bottom:8px}
.chart-legend{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:6px}
.chart-key{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:var(--gray)}
.chart-dot{width:8px;height:8px;border-radius:50%;display:inline-block}
@media(max-width:640px){.header,.hero{padding-left:20px;padding-right:20px}.wrap{padding:0 16px}.card{padding:24px 20px}}
`;

function scoreCls(v, invert) {
  if (v === null || v === undefined) return 'mid';
  if (invert) return v >= 25 ? 'lo' : v >= 8 ? 'mid' : 'hi';
  return v >= 70 ? 'hi' : v >= 40 ? 'mid' : 'lo';
}
function trendArrow(v, invert) {
  if (v === null || v === undefined) return '';
  const good = invert ? v < 0 : v > 0;
  const color = v === 0 ? 'var(--gray-light)' : good ? 'var(--green)' : 'var(--red)';
  const arrow = v > 0 ? '▲' : v < 0 ? '▼' : '＝';
  return `<span class="kpi-trend" style="color:${color}">${arrow} ${Math.abs(v).toLocaleString('pt-BR')}% vs anterior</span>`;
}
function sevTag(sev) {
  const s = String(sev || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const map = { critica: 'critical', alta: 'serious', media: 'moderate', baixa: 'minor' };
  return `<span class="impact-tag ${map[s] || 'moderate'}">${esc(sev)}</span>`;
}
function sevItemCls(sev) {
  const s = String(sev || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  return (s === 'critica' || s === 'alta') ? 'fail' : s === 'media' ? 'warning' : 'pass';
}
function urgBadge(u) {
  const s = String(u || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const cls = (s === 'critica' || s === 'alta') ? 'poor' : s === 'media' ? 'fair' : 'good';
  return `<span class="geo-badge ${cls}">urgência ${esc(u || 'média')}</span>`;
}
function section(icon, title, bodyHtml, open) {
  if (!bodyHtml) return '';
  return `<div class="section">
    <div class="section-head" onclick="tg(this)"><div class="section-title">${icon} ${esc(title)}</div><span class="chev">${open ? '▾' : '▸'}</span></div>
    <div class="section-body${open ? '' : ' hidden'}">${bodyHtml}</div>
  </div>`;
}
function frictionTable(title, rows) {
  if (!rows || !rows.length) return '';
  const tr = rows.map(r => {
    const f = r.friction || {};
    const p = k => f[k]?.pct !== undefined ? pct(f[k].pct) : '—';
    const sc = r.frictionScore >= 25 ? 'var(--red)' : r.frictionScore >= 15 ? '#ea580c' : r.frictionScore >= 8 ? 'var(--yellow)' : 'var(--green)';
    return `<tr>
      <td>${esc(r.dimension)}</td>
      <td class="r">${fmt(r.sessions)}</td>
      <td class="c"><span class="score-pill" style="color:${sc}">${fmt(r.frictionScore)}</span></td>
      <td class="c">${p('rageClicks')}</td>
      <td class="c">${p('deadClicks')}</td>
      <td class="c">${p('quickbacks')}</td>
      <td class="c">${r.scrollDepth !== null && r.scrollDepth !== undefined ? pct(r.scrollDepth) : '—'}</td>
    </tr>`;
  }).join('');
  return `<div class="tbl-title">${esc(title)}</div><div class="tbl-wrap"><table class="tbl">
    <tr><th>Dimensão</th><th class="r">Sessões</th><th class="c">Score Fricção</th><th class="c">Rage %</th><th class="c">Dead %</th><th class="c">Quickback %</th><th class="c">Scroll médio</th></tr>
    ${tr}</table></div>`;
}

function page(heroExtra, inner) {
  return `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>IA Clarity Tracker - MIT</title>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>${CSS}</style></head><body>
<header class="header"><div class="header-inner">
  <img src="https://creativosbr.com.br/wp-content/uploads/2022/08/cadastra-1638546176-logopng.png" class="logo" alt="Cadastra">
  <div class="product-name">IA Clarity <span>Tracker</span></div>
  <span class="version-badge">MIT</span>
</div></header>
<section class="hero"><div class="hero-inner">
  <div class="hero-eyebrow">CRO · UX RESEARCH · BEHAVIOR ANALYTICS</div>
  <h1>Auditoria CRO/UX — Microsoft Clarity</h1>
  <p class="hero-desc">Monitoramento diário de fricção e engajamento com dados comportamentais do Microsoft Clarity: rage clicks, dead clicks, quickbacks, scroll e erros — com diagnóstico e recomendações geradas por IA.</p>
  <div class="hero-badges">
    <div class="hero-badge">Rage Clicks</div><div class="hero-badge">Dead Clicks</div>
    <div class="hero-badge">Quickbacks</div><div class="hero-badge">Scroll Depth</div>
    <div class="hero-badge">Erros de Script</div><div class="hero-badge">Score de Frustração</div>
    <div class="hero-badge">Tendências</div><div class="hero-badge">IA Insights</div>
  </div>
  ${heroExtra}
</div></section>
<div class="wrap">${inner}
  <p class="footer-note">Gerado automaticamente via n8n + Microsoft Clarity Data Export API · cortes vazios indicam chamadas sem dados no período</p>
</div>
<script>function tg(h){const b=h.nextElementSibling;b.classList.toggle('hidden');h.querySelector('.chev').textContent=b.classList.contains('hidden')?'▸':'▾'}</script>
</body></html>`;
}

// ── Estado vazio ─────────────────────────────────────────────
if (!row) {
  const html = page('', `<div class="card">
    <div class="card-title">Nenhum snapshot disponível ainda</div>
    <div class="card-sub">Execute o workflow de auditoria (agendado diariamente ou manualmente) para gerar o primeiro relatório. Os snapshots aparecerão aqui automaticamente, com seletor de data.</div>
  </div>`);
  return [{ json: { html } }];
}

// ── Evolução dos últimos dias (todos os snapshots, até 14) ───
const histRows = rowsRaw.slice(0, 14).slice().reverse(); // mais antigo → mais recente
const hist = histRows.map(r => {
  const m = parse(r.metrics) || {};
  const o = m.overview || {};
  const f2 = o.frictionRates || {};
  return {
    date: String(r.snapshotDate),
    frustrationScore: o.frustrationScore ?? null,
    sessions: o.sessions ?? null,
    rage: f2.rageClicks?.pctSessions ?? null,
    dead: f2.deadClicks?.pctSessions ?? null,
    quick: f2.quickbacks?.pctSessions ?? null,
    scroll: o.avgScrollDepth ?? null
  };
});

// Gráfico de linhas em SVG puro (sem dependências externas)
function lineChart(series, opts) {
  const W = 460, H = 190, PL = 46, PR = 16, PT = 14, PB = 30;
  const pts = series.flatMap(s => s.values.filter(p => p.v !== null && p.v !== undefined));
  if (!pts.length) return '';
  const ds = [...new Set(series.flatMap(s => s.values.map(p => p.d)))].sort();
  let ymin = Math.min(...pts.map(p => p.v), 0);
  let ymax = Math.max(...pts.map(p => p.v));
  if (ymax === ymin) ymax = ymin + 1;
  ymax = ymax + (ymax - ymin) * 0.12;
  const x = d => { const i = ds.indexOf(d); return PL + (ds.length === 1 ? (W - PL - PR) / 2 : i * (W - PL - PR) / (ds.length - 1)); };
  const y = v => PT + (H - PT - PB) * (1 - (v - ymin) / (ymax - ymin));
  let grid = '';
  for (let i = 0; i <= 3; i++) {
    const gv = ymin + (ymax - ymin) * i / 3, gy = y(gv);
    const lbl = Number(gv.toFixed(Math.abs(ymax - ymin) < 20 ? 1 : 0)).toLocaleString('pt-BR');
    grid += `<line x1="${PL}" y1="${gy.toFixed(1)}" x2="${W - PR}" y2="${gy.toFixed(1)}" stroke="#e5e7eb" stroke-width="1"/><text x="${PL - 6}" y="${(gy + 3.5).toFixed(1)}" text-anchor="end" font-size="10" fill="#9ca3af">${lbl}</text>`;
  }
  const xi = [...new Set([0, Math.floor((ds.length - 1) / 2), ds.length - 1])];
  let xlbl = '';
  for (const i of xi) xlbl += `<text x="${x(ds[i]).toFixed(1)}" y="${H - 8}" text-anchor="middle" font-size="10" fill="#9ca3af">${esc(ds[i].slice(5))}</text>`;
  let marks = '';
  for (const s of series) {
    const vs = s.values.filter(p => p.v !== null && p.v !== undefined);
    if (!vs.length) continue;
    marks += `<path d="${vs.map((p, i) => `${i ? 'L' : 'M'}${x(p.d).toFixed(1)},${y(p.v).toFixed(1)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>`;
    marks += vs.map(p => `<circle cx="${x(p.d).toFixed(1)}" cy="${y(p.v).toFixed(1)}" r="3.5" fill="${s.color}" stroke="#fff" stroke-width="2"><title>${esc(s.label)} · ${esc(p.d)}: ${Number(p.v).toLocaleString('pt-BR')}</title></circle>`).join('');
    const lastP = vs[vs.length - 1];
    marks += `<text x="${Math.min(x(lastP.d), W - 20).toFixed(1)}" y="${(y(lastP.v) - 9).toFixed(1)}" text-anchor="middle" font-size="10" font-weight="700" fill="${s.color}">${Number(lastP.v).toLocaleString('pt-BR')}</text>`;
  }
  const legend = series.length > 1
    ? `<div class="chart-legend">${series.map(s => `<span class="chart-key"><span class="chart-dot" style="background:${s.color}"></span>${esc(s.label)}</span>`).join('')}</div>`
    : '';
  return `<div class="chart-box"><div class="chart-title">${esc(opts.title)}</div>${legend}<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(opts.title)}" style="width:100%;height:auto">${grid}${xlbl}${marks}</svg></div>`;
}
const mkSeries = (key, label, color) => ({ label, color, values: hist.map(h => ({ d: h.date, v: h[key] })) });
const evolCard = hist.length >= 2 ? `<div class="card">
  <div class="card-title">📈 Evolução dos últimos dias</div>
  <div class="card-sub">Histórico dos últimos ${hist.length} snapshots diários salvos na Data Table. Passe o mouse sobre os pontos para ver os valores exatos.</div>
  <div class="chart-grid">
    ${lineChart([mkSeries('frustrationScore', 'Score de Frustração', '#e84e1b')], { title: 'Score de Frustração (0–100)' })}
    ${lineChart([mkSeries('sessions', 'Sessões', '#e84e1b')], { title: 'Sessões' })}
    ${lineChart([mkSeries('rage', 'Rage clicks', '#2563eb'), mkSeries('dead', 'Dead clicks', '#ea580c'), mkSeries('quick', 'Quickbacks', '#7c3aed')], { title: '% de sessões com fricção' })}
    ${lineChart([mkSeries('scroll', 'Scroll médio', '#e84e1b')], { title: 'Scroll médio (%)' })}
  </div>
</div>` : '';

// ── Dados do snapshot selecionado ────────────────────────────
const data = parse(row.metrics) || {};
const analysis = parse(row.analysis) || {};
const ov = data.overview || {};
const fr = ov.frictionRates || {};
const t  = data.trends || {};
const re = analysis.resumo_executivo || {};

const dateSelector = `<div class="date-pick"><label>Snapshot</label>
  <select onchange="location.href='?date='+this.value">
    ${dates.map(d => `<option value="${esc(d)}"${d === selDate ? ' selected' : ''}>${esc(d)}</option>`).join('')}
  </select></div>`;

const kpi = (lbl, val, trend) => `<div class="kpi"><div class="kpi-val">${val}</div><div class="kpi-lbl">${esc(lbl)}</div>${trend || ''}</div>`;
const fsCls = scoreCls(ov.frustrationScore, true);
const fsColor = fsCls === 'hi' ? 'var(--green)' : fsCls === 'mid' ? 'var(--yellow)' : 'var(--red)';

const alertsHtml = (data.alerts || []).length ? `<div class="infra-alert">
  <div class="infra-alert-head">🚨 ${data.alerts.length} página(s) acima do limite de fricção</div>
  <ul>${data.alerts.map(a => `<li>${esc(a.url)} — score <b>${fmt(a.frictionScore)}</b> (${fmt(a.sessions)} sessões)</li>`).join('')}</ul>
</div>` : '';

// Erros das chamadas à Data Export API (token inválido, limite diário...)
const apiErrs = Object.entries(data.apiStatus?.erros || {});
const apiErrsHtml = apiErrs.length ? `<div class="infra-alert" style="background:var(--yellow-bg);border-color:var(--yellow-border)">
  <div class="infra-alert-head" style="color:var(--yellow)">⚠️ Chamadas à API do Clarity sem dados neste snapshot</div>
  <ul style="color:#713f12">${apiErrs.map(([k, v]) => `<li><b>${esc(k)}:</b> ${esc(v)}</li>`).join('')}</ul>
  <div style="font-size:12px;color:#854d0e;margin-top:6px">Causas comuns: credencial Header Auth incorreta (Name deve ser exatamente <b>Authorization</b>, Value <b>Bearer SEU_TOKEN</b>) ou limite de 10 chamadas/dia da API excedido.</div>
</div>` : '';

const overviewCard = `<div class="card">
  <div class="card-title">📊 Visão Geral</div>
  <div class="card-sub">${esc(data.projectName)} · últimos ${esc(data.periodDays)} dia(s) · gerado em ${new Date(data.generatedAt).toLocaleString('pt-BR')}${t.comparadoCom ? ' · comparado com ' + esc(t.comparadoCom) : ''}</div>
  <div class="kpi-grid">
    ${kpi('Sessões', fmt(ov.sessions), trendArrow(t.sessionsPct, false))}
    ${kpi('Usuários únicos', fmt(ov.users), trendArrow(t.usersPct, false))}
    ${kpi('Score Frustração', `<span style="color:${fsColor}">${fmt(ov.frustrationScore)}</span>`, trendArrow(t.frustrationScorePct, true))}
    ${kpi('Scroll médio', pct(ov.avgScrollDepth), trendArrow(t.scrollDepthPct, false))}
    ${kpi('Tempo ativo/sessão', mmss(ov.avgActiveTimeSec))}
    ${kpi('Rage clicks', pct(fr.rageClicks?.pctSessions), trendArrow(t.rageClicksPct, true))}
    ${kpi('Dead clicks', pct(fr.deadClicks?.pctSessions), trendArrow(t.deadClicksPct, true))}
    ${kpi('Tráfego bot', pct(ov.botPct))}
  </div>
  <div class="sev-legend">Cortes coletados — URLs: ${data.apiStatus?.porUrl ?? 0} · Dispositivos: ${data.apiStatus?.porDispositivo ?? 0} · Origens: ${data.apiStatus?.origemTrafego ?? 0} · Navegador/SO: ${data.apiStatus?.navegadorSo ?? 0}</div>
  ${apiErrsHtml}
  ${alertsHtml}
</div>`;

const resumoHtml = `
  <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:12px">
    ${re.nota_geral !== null && re.nota_geral !== undefined ? `<div><span class="score-frac ${scoreCls(re.nota_geral, false)}">${esc(re.nota_geral)}</span><span style="color:var(--gray-light);font-weight:700">/100</span><div class="kpi-lbl" style="margin-top:2px">Nota UX (IA)</div></div>` : ''}
    ${urgBadge(re.nivel_urgencia)}
  </div>
  <p style="font-size:14px;color:var(--dark);line-height:1.7">${esc(re.sintese)}</p>`;

const diagHtml = (analysis.diagnostico || []).map(d => `<div class="audit-item ${sevItemCls(d.severidade)}">
  <div class="audit-head">${sevTag(d.severidade)}<span class="audit-title">${esc(d.area)}</span></div>
  <div class="audit-finding">${esc(d.achado)}</div>
  <div class="audit-finding">📊 ${esc(d.evidencia)}</div>
  ${d.causa_provavel ? `<div class="audit-rec">💡 Causa provável: ${esc(d.causa_provavel)}</div>` : ''}
</div>`).join('');

const qwHtml = (analysis.quick_wins || []).map((q2, i) => `<div class="feat-item">
  <div class="feat-check">${i + 1}</div>
  <div><b>${esc(q2.acao)}</b><br><span style="color:var(--gray)">${esc(q2.motivo)}</span>
  <span style="color:var(--gray-light);font-size:12px"> · ${esc(q2.pagina_alvo || '')} · ⏱ ${esc(q2.prazo || '')}</span></div>
</div>`).join('');

const invHtml = (analysis.investigar_no_clarity || []).map(v => `<div class="check-block">
  <div class="check-head"><span class="tool-badge">${esc(v.ferramenta)}</span><span class="audit-title">${esc(v.o_que)}</span></div>
  <div class="filter-code">🔎 ${esc(v.filtro_sugerido)}</div>
  <div class="check-q">❓ ${esc(v.pergunta_a_responder)}</div>
</div>`).join('');

const cortesHtml =
  frictionTable('Páginas com maior fricção', data.byUrl) +
  frictionTable('Por dispositivo', data.byDevice) +
  frictionTable('Por origem de tráfego (Source · Medium · Campaign)', data.bySource) +
  frictionTable('Por navegador e sistema (erros técnicos)', data.byTech);

const inner = overviewCard +
  evolCard +
  section('💡', 'Resumo Executivo', resumoHtml, true) +
  section('🔍', 'Diagnóstico de Fricção', diagHtml, true) +
  section('⚡', 'Quick Wins', qwHtml, false) +
  section('🎥', 'Investigar manualmente no Clarity', invHtml, false) +
  section('📋', 'Dados por corte', cortesHtml, false);

return [{ json: { html: page(dateSelector, inner) } }];

// ============================================================
// Consolida os snapshots do Clarity dos últimos 7 dias e os
// dados diários do GA4, alinha por data e calcula correlações
// ============================================================
const cfg = $('Config Semanal').first().json;
const lookback = parseInt(cfg.lookbackDays) || 7;
const cutoff = new Date(Date.now() - lookback * 864e5).toISOString().slice(0, 10);

const parse = v => { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { return null; } };

// ── Clarity: snapshots diários da Data Table ─────────────────
const snaps = $('Ler Snapshots (Semanal)').all().map(i => i.json)
  .filter(r => r && r.snapshotDate && String(r.snapshotDate) >= cutoff)
  .filter(r => !cfg.projectName || r.projectName === cfg.projectName)
  .sort((a, b) => String(a.snapshotDate).localeCompare(String(b.snapshotDate)))
  .map(r => {
    const m = parse(r.metrics) || {};
    const o = m.overview || {};
    const fr = o.frictionRates || {};
    const an = parse(r.analysis) || {};
    return {
      date: String(r.snapshotDate),
      frustrationScore: o.frustrationScore ?? null,
      sessions: o.sessions ?? null,
      users: o.users ?? null,
      scroll: o.avgScrollDepth ?? null,
      ragePct: fr.rageClicks?.pctSessions ?? null,
      deadPct: fr.deadClicks?.pctSessions ?? null,
      quickPct: fr.quickbacks?.pctSessions ?? null,
      alerts: (m.alerts || []).map(a => ({ url: a.url, frictionScore: a.frictionScore, sessions: a.sessions })),
      topUrls: (m.byUrl || []).slice(0, 8).map(u => ({ url: u.dimension, frictionScore: u.frictionScore, sessions: u.sessions })),
      sinteseIA: an.resumo_executivo?.sintese || null
    };
  });

// ── GA4: métricas diárias (tolerante à ausência de credencial) ─
let ga = [];
try {
  ga = $('GA – Métricas Diárias').all().map(i => i.json)
    .filter(r => r && r.date)
    .map(r => {
      const d = String(r.date);
      const iso = d.length === 8 ? `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}` : d;
      const n = v => { const x = parseFloat(v); return isNaN(x) ? null : x; };
      const sess = n(r.sessions), engDur = n(r.userEngagementDuration);
      return {
        date: iso,
        sessions: sess,
        users: n(r.totalUsers),
        pageViews: n(r.screenPageViews),
        engagementRate: r.engagementRate !== undefined ? Math.round(n(r.engagementRate) * 1000) / 10 : null,
        avgEngagementSec: (engDur !== null && sess) ? Math.round(engDur / sess) : null
      };
    })
    .filter(r => r.date >= cutoff)
    .sort((a, b) => a.date.localeCompare(b.date));
} catch (e) { ga = []; }
const gaOk = ga.length > 0;

// ── Agregados da semana (Clarity) ────────────────────────────
const avg = arr => { const v = arr.filter(x => x !== null && x !== undefined); return v.length ? Math.round(v.reduce((a, b) => a + b, 0) / v.length * 10) / 10 : null; };
const sum = arr => arr.filter(x => x !== null && x !== undefined).reduce((a, b) => a + b, 0);
const delta = (a, b) => (a === null || b === null || a === undefined || b === undefined || !b) ? null : Math.round((a - b) / b * 1000) / 10;

const first = snaps[0] || {};
const last = snaps[snaps.length - 1] || {};
const resumoClarity = {
  diasComSnapshot: snaps.length,
  sessoesTotais: sum(snaps.map(s => s.sessions)),
  frustracaoMedia: avg(snaps.map(s => s.frustrationScore)),
  frustracaoInicio: first.frustrationScore ?? null,
  frustracaoFim: last.frustrationScore ?? null,
  variacaoFrustracaoPct: delta(last.frustrationScore, first.frustrationScore),
  rageMedioPct: avg(snaps.map(s => s.ragePct)),
  deadMedioPct: avg(snaps.map(s => s.deadPct)),
  quickbackMedioPct: avg(snaps.map(s => s.quickPct)),
  scrollMedioPct: avg(snaps.map(s => s.scroll))
};

// URLs recorrentes no topo de fricção durante a semana
const urlAgg = {};
for (const s of snaps) for (const u of s.topUrls) {
  if (!urlAgg[u.url]) urlAgg[u.url] = { url: u.url, dias: 0, scoreMedio: 0, sessoes: 0 };
  urlAgg[u.url].dias++;
  urlAgg[u.url].scoreMedio += u.frictionScore || 0;
  urlAgg[u.url].sessoes += u.sessions || 0;
}
const urlsRecorrentes = Object.values(urlAgg)
  .map(u => ({ ...u, scoreMedio: Math.round(u.scoreMedio / u.dias * 10) / 10 }))
  .sort((a, b) => b.dias - a.dias || b.scoreMedio - a.scoreMedio)
  .slice(0, 10);

// ── Correlação Clarity × GA (Pearson por dia alinhado) ───────
function pearson(xs, ys) {
  const n = xs.length;
  if (n < 3) return null;
  const mx = xs.reduce((a, b) => a + b, 0) / n, my = ys.reduce((a, b) => a + b, 0) / n;
  let num = 0, dx = 0, dy = 0;
  for (let i = 0; i < n; i++) { num += (xs[i] - mx) * (ys[i] - my); dx += (xs[i] - mx) ** 2; dy += (ys[i] - my) ** 2; }
  if (!dx || !dy) return null;
  return Math.round(num / Math.sqrt(dx * dy) * 100) / 100;
}
const aligned = snaps.map(s => ({ s, g: ga.find(g => g.date === s.date) })).filter(p => p.g);
const corrOf = (fa, fb) => {
  const ps = aligned.filter(p => fa(p) !== null && fa(p) !== undefined && fb(p) !== null && fb(p) !== undefined);
  return pearson(ps.map(fa), ps.map(fb));
};
const correlacoes = gaOk ? {
  diasAlinhados: aligned.length,
  frustracao_vs_engajamentoGA: corrOf(p => p.s.frustrationScore, p => p.g.engagementRate),
  frustracao_vs_sessoesGA: corrOf(p => p.s.frustrationScore, p => p.g.sessions),
  rage_vs_engajamentoGA: corrOf(p => p.s.ragePct, p => p.g.engagementRate),
  quickback_vs_engajamentoGA: corrOf(p => p.s.quickPct, p => p.g.engagementRate),
  nota: 'Correlação de Pearson (-1 a 1) entre dias alinhados; snapshots do Clarity agregam os últimos ' + (parseInt(cfg.clarityPeriodDays) || 3) + ' dias, portanto trate como tendência, não causalidade.'
} : { diasAlinhados: 0, nota: 'GA indisponível nesta execução (credencial/propriedade não configurada ou sem dados).' };

return [{ json: {
  geradoEm: new Date().toISOString(),
  projectName: cfg.projectName || 'Meu Projeto',
  emails: cfg.reportEmails,
  periodo: { de: snaps[0]?.date || cutoff, ate: last.date || new Date().toISOString().slice(0, 10) },
  resumoClarity,
  clarityDiario: snaps.map(({ sinteseIA, topUrls, ...rest }) => rest),
  urlsRecorrentes,
  gaOk,
  gaDiario: ga,
  correlacoes,
  ultimaSinteseIA: last.sinteseIA || null
} }];

parameters.text:
=Você é um consultor sênior de CRO/UX e Web Analytics. Analise a evolução da última semana correlacionando o comportamento do Microsoft Clarity (fricção) com as métricas de audiência do Google Analytics 4.

## PERÍODO
Projeto: {{ $json.projectName }} | De {{ $json.periodo.de }} a {{ $json.periodo.ate }}

## DADOS CONSOLIDADOS DA SEMANA
{{ JSON.stringify({ resumoClarity: $json.resumoClarity, clarityDiario: $json.clarityDiario, urlsRecorrentes: $json.urlsRecorrentes, gaDisponivel: $json.gaOk, gaDiario: $json.gaDiario, correlacoesNumericas: $json.correlacoes }) }}

## GLOSSÁRIO
- frustrationScore: índice 0–100 (rage 35%, dead 20%, quickback 15%, scroll excessivo 10%, error clicks 10%, script errors 10%). Maior = pior.
- Correlação de Pearson (-1 a 1): |r|≥0,7 forte, 0,4–0,7 moderada, <0,4 fraca. Os snapshots do Clarity agregam alguns dias, então trate correlação como TENDÊNCIA, nunca como causalidade comprovada.
- GA: sessions, totalUsers, screenPageViews, engagementRate (% sessões engajadas), avgEngagementSec.

## SUA TAREFA
Escreva um resumo semanal executivo e acionável. Cite números exatos dos dados. Correlacione explicitamente os padrões de fricção do Clarity com o que aconteceu no GA na mesma janela (ex.: "dias com pico de rage clicks coincidiram com queda na taxa de engajamento do GA"). Se o GA estiver indisponível (gaDisponivel=false), baseie-se só no Clarity e diga isso.

Responda SOMENTE com JSON válido (sem markdown, sem cercas), exatamente neste schema:
{
  "resumo_da_semana": "<4-6 frases: como a semana evoluiu, principal padrão Clarity×GA, e o foco da próxima semana>",
  "destaques": [
    { "tipo": "positivo|negativo|neutro", "titulo": "<curto>", "detalhe": "<números exatos>" }
  ],
  "correlacoes_ga_clarity": [
    { "padrao_clarity": "<métrica/comportamento do Clarity>", "metrica_ga": "<métrica do GA>", "leitura": "<o que a relação sugere na prática>", "confianca": "alta|média|baixa" }
  ],
  "recomendacoes_proxima_semana": [
    { "acao": "<ação concreta>", "motivo": "<por quê, ligado aos dados>", "prioridade": "alta|media|baixa" }
  ]
}
Regras: destaques 3-5 itens; correlacoes_ga_clarity 2-4 itens (se GA indisponível, deixe [] e explique no resumo); recomendacoes_proxima_semana 3-5 itens ordenadas por prioridade.

parameters.jsCode:
// ============================================================
// Extrai o JSON da análise semanal da IA e monta o e-mail em
// HTML compatível com clientes de e-mail (estilos inline)
// ============================================================
const raw = $input.first().json;
let text = raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

let ai = null;
try { ai = JSON.parse(text); } catch (e) {
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) { try { ai = JSON.parse(fence[1]); } catch (e2) {} }
  if (!ai) { const m = text.match(/\{[\s\S]*\}/); if (m) { try { ai = JSON.parse(m[0]); } catch (e3) {} } }
}
if (!ai) ai = { resumo_da_semana: text.slice(0, 1500) || 'Análise indisponível nesta execução.', destaques: [], correlacoes_ga_clarity: [], recomendacoes_proxima_semana: [] };

const d = $('Montar Resumo Semanal').first().json;
const rc = d.resumoClarity || {};

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR');
const pct = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR') + '%';

const OX = '#e84e1b', DARK = '#111827', GRAY = '#6b7280', LINE = '#e5e7eb', SOFT = '#f3f4f6';
const GREEN = '#059669', RED = '#dc2626', YELLOW = '#d97706';

const deltaTxt = v => {
  if (v === null || v === undefined) return '';
  const good = v < 0; // frustração: queda é boa
  return `<span style="color:${good ? GREEN : RED};font-weight:700">${v > 0 ? '▲' : '▼'} ${Math.abs(v).toLocaleString('pt-BR')}%</span>`;
};

const kpiCell = (lbl, val, extra) => `<td width="25%" style="background:${SOFT};border:1px solid ${LINE};border-top:3px solid ${OX};border-radius:8px;padding:12px;text-align:center">
  <div style="font-size:20px;font-weight:800;color:${DARK}">${val}</div>
  <div style="font-size:10px;font-weight:700;color:${GRAY};text-transform:uppercase;letter-spacing:.05em">${esc(lbl)}</div>${extra || ''}
</td>`;

// Barra simples (compatível com e-mail) para o score diário
const barRow = (label, v, max) => {
  const w = (v === null || !max) ? 0 : Math.max(2, Math.round(v / max * 100));
  const color = v >= 25 ? RED : v >= 15 ? '#ea580c' : v >= 8 ? YELLOW : GREEN;
  return `<tr>
    <td style="font-size:12px;color:${GRAY};padding:3px 8px 3px 0;white-space:nowrap">${esc(label)}</td>
    <td width="100%" style="padding:3px 0">
      <table cellpadding="0" cellspacing="0" width="100%"><tr>
        <td width="${w}%" style="background:${color};height:10px;border-radius:5px;font-size:0;line-height:0">&nbsp;</td>
        <td style="font-size:11px;font-weight:700;color:${DARK};padding-left:6px;white-space:nowrap">${fmt(v)}</td>
        <td width="${100 - w}%"></td>
      </tr></table>
    </td>
  </tr>`;
};
const maxScore = Math.max(...(d.clarityDiario || []).map(s => s.frustrationScore || 0), 1);
const dailyBars = (d.clarityDiario || []).map(s => barRow(s.date, s.frustrationScore, maxScore)).join('');

// Tabela diária Clarity × GA
const gaRows = (d.clarityDiario || []).map(s => {
  const g = (d.gaDiario || []).find(g2 => g2.date === s.date) || {};
  return `<tr>
    <td style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${esc(s.date)}</td>
    <td align="right" style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${fmt(s.frustrationScore)}</td>
    <td align="right" style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${pct(s.ragePct)}</td>
    <td align="right" style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px;border-left:2px solid ${LINE}">${fmt(g.sessions)}</td>
    <td align="right" style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${fmt(g.users)}</td>
    <td align="right" style="padding:7px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${pct(g.engagementRate)}</td>
  </tr>`;
}).join('');
const th = t => `<th align="right" style="padding:7px 8px;font-size:10px;font-weight:800;color:${GRAY};text-transform:uppercase;letter-spacing:.05em;background:${SOFT};border-bottom:1px solid ${LINE}">${t}</th>`;

const corr = d.correlacoes || {};
const corrChip = v => {
  if (v === null || v === undefined) return `<span style="color:${GRAY}">n/d</span>`;
  const a = Math.abs(v);
  const força = a >= 0.7 ? 'forte' : a >= 0.4 ? 'moderada' : 'fraca';
  const color = a >= 0.7 ? RED : a >= 0.4 ? YELLOW : GRAY;
  return `<b style="color:${color}">${v.toLocaleString('pt-BR')}</b> <span style="color:${GRAY};font-size:11px">(${força})</span>`;
};
const corrHtml = d.gaOk ? `<table cellpadding="0" cellspacing="0" width="100%" style="font-size:12px;color:${DARK}">
  <tr><td style="padding:4px 0">Frustração (Clarity) × Taxa de engajamento (GA)</td><td align="right">${corrChip(corr.frustracao_vs_engajamentoGA)}</td></tr>
  <tr><td style="padding:4px 0">Frustração (Clarity) × Sessões (GA)</td><td align="right">${corrChip(corr.frustracao_vs_sessoesGA)}</td></tr>
  <tr><td style="padding:4px 0">Rage clicks (Clarity) × Engajamento (GA)</td><td align="right">${corrChip(corr.rage_vs_engajamentoGA)}</td></tr>
  <tr><td style="padding:4px 0">Quickbacks (Clarity) × Engajamento (GA)</td><td align="right">${corrChip(corr.quickback_vs_engajamentoGA)}</td></tr>
</table>
<p style="font-size:11px;color:${GRAY};margin:8px 0 0">${esc(corr.nota || '')} Dias alinhados: ${fmt(corr.diasAlinhados)}.</p>`
: `<p style="font-size:12px;color:${YELLOW};margin:0"><b>⚠️ Dados do GA indisponíveis nesta execução.</b> Configure a credencial do Google Analytics e o ID da propriedade GA4 no nó "Config Semanal" para habilitar a correlação.</p>`;

const tipoColor = t => { const s = String(t || '').toLowerCase(); return s === 'positivo' ? GREEN : s === 'negativo' ? RED : GRAY; };
const destaquesHtml = (ai.destaques || []).map(x => `<tr><td style="padding:6px 0;font-size:13px;line-height:1.55">
  <span style="color:${tipoColor(x.tipo)};font-weight:800">●</span> <b>${esc(x.titulo)}</b> — ${esc(x.detalhe)}
</td></tr>`).join('');

const corrIAHtml = (ai.correlacoes_ga_clarity || []).map(x => `<tr><td style="padding:8px 10px;border-left:3px solid ${OX};background:${SOFT};border-radius:6px;font-size:12.5px;line-height:1.55">
  <b>${esc(x.padrao_clarity)}</b> ↔ <b>${esc(x.metrica_ga)}</b><br>${esc(x.leitura)}
  <span style="color:${GRAY};font-size:11px"> · confiança ${esc(x.confianca || 'média')}</span>
</td></tr><tr><td style="font-size:6px;line-height:6px">&nbsp;</td></tr>`).join('');

const prioColor = p => { const s = String(p || '').toLowerCase(); return s === 'alta' ? RED : s === 'media' || s === 'média' ? YELLOW : GRAY; };
const recsHtml = (ai.recomendacoes_proxima_semana || []).map((r, i) => `<tr><td style="padding:6px 0;font-size:13px;line-height:1.55">
  <b>${i + 1}.</b> ${esc(r.acao)} <span style="color:${prioColor(r.prioridade)};font-weight:700;font-size:11px">[${esc(r.prioridade || 'média')}]</span><br>
  <span style="color:${GRAY};font-size:12px">${esc(r.motivo)}</span>
</td></tr>`).join('');

const urlsHtml = (d.urlsRecorrentes || []).slice(0, 6).map(u => `<tr>
  <td style="padding:6px 8px;border-bottom:1px solid ${SOFT};font-size:12px;word-break:break-all">${esc(u.url)}</td>
  <td align="center" style="padding:6px 8px;border-bottom:1px solid ${SOFT};font-size:12px">${fmt(u.dias)}</td>
  <td align="right" style="padding:6px 8px;border-bottom:1px solid ${SOFT};font-size:12px;font-weight:700">${fmt(u.scoreMedio)}</td>
</tr>`).join('');

const sec = (title, body) => `<tr><td style="padding:22px 28px;border-top:1px solid ${LINE}">
  <div style="font-size:14px;font-weight:800;color:${DARK};margin-bottom:10px">${title}</div>${body}
</td></tr>`;

const html = `<!DOCTYPE html><html lang="pt-BR"><body style="margin:0;padding:0;background:#f4f4f2">
<table cellpadding="0" cellspacing="0" width="100%" style="background:#f4f4f2;padding:24px 0"><tr><td align="center">
<table cellpadding="0" cellspacing="0" width="640" style="max-width:640px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;font-family:Arial,Helvetica,sans-serif;box-shadow:0 2px 12px rgba(0,0,0,.08)">
  <tr><td style="background:linear-gradient(140deg,#e84e1b,#ff6b3d);background-color:#e84e1b;padding:26px 28px;color:#ffffff">
    <div style="font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;opacity:.85">IA Clarity Tracker · Resumo Semanal</div>
    <div style="font-size:22px;font-weight:800;margin-top:4px">${esc(d.projectName)} — Semana de ${esc(d.periodo?.de)} a ${esc(d.periodo?.ate)}</div>
  </td></tr>
  <tr><td style="padding:22px 28px">
    <table cellpadding="0" cellspacing="6" width="100%"><tr>
      ${kpiCell('Sessões (soma)', fmt(rc.sessoesTotais))}
      ${kpiCell('Frustração média', fmt(rc.frustracaoMedia), rc.variacaoFrustracaoPct !== null ? `<div style="font-size:11px;margin-top:2px">${deltaTxt(rc.variacaoFrustracaoPct)} na semana</div>` : '')}
      ${kpiCell('Rage clicks méd.', pct(rc.rageMedioPct))}
      ${kpiCell('Dead clicks méd.', pct(rc.deadMedioPct))}
    </tr></table>
  </td></tr>
  ${sec('💡 Resumo da semana (IA)', `<p style="font-size:13px;color:${DARK};line-height:1.65;margin:0">${esc(ai.resumo_da_semana)}</p>`)}
  ${destaquesHtml ? sec('⭐ Destaques', `<table cellpadding="0" cellspacing="0" width="100%">${destaquesHtml}</table>`) : ''}
  ${sec('📉 Score de Frustração por dia', `<table cellpadding="0" cellspacing="0" width="100%">${dailyBars || '<tr><td style="font-size:12px;color:' + GRAY + '">Sem snapshots no período.</td></tr>'}</table>`)}
  ${sec('🔗 Correlação GA × Clarity (números)', corrHtml)}
  ${corrIAHtml ? sec('🧠 Leitura das correlações (IA)', `<table cellpadding="0" cellspacing="0" width="100%">${corrIAHtml}</table>`) : ''}
  ${sec('📅 Diário: Clarity × GA', `<table cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse">
    <tr><th align="left" style="padding:7px 8px;font-size:10px;font-weight:800;color:${GRAY};text-transform:uppercase;background:${SOFT};border-bottom:1px solid ${LINE}">Data</th>${th('Frustração')}${th('Rage %')}${th('Sessões GA')}${th('Usuários GA')}${th('Engaj. GA')}</tr>
    ${gaRows || `<tr><td colspan="6" style="font-size:12px;color:${GRAY};padding:8px">Sem dados no período.</td></tr>`}
  </table>`)}
  ${urlsHtml ? sec('🚨 Páginas recorrentes com fricção', `<table cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse">
    <tr><th align="left" style="padding:6px 8px;font-size:10px;font-weight:800;color:${GRAY};text-transform:uppercase;background:${SOFT};border-bottom:1px solid ${LINE}">URL</th><th align="center" style="padding:6px 8px;font-size:10px;font-weight:800;color:${GRAY};text-transform:uppercase;background:${SOFT};border-bottom:1px solid ${LINE}">Dias no topo</th><th align="right" style="padding:6px 8px;font-size:10px;font-weight:800;color:${GRAY};text-transform:uppercase;background:${SOFT};border-bottom:1px solid ${LINE}">Score médio</th></tr>
    ${urlsHtml}</table>`) : ''}
  ${recsHtml ? sec('✅ Recomendações para a próxima semana', `<table cellpadding="0" cellspacing="0" width="100%">${recsHtml}</table>`) : ''}
  <tr><td style="padding:18px 28px;border-top:1px solid ${LINE};text-align:center">
    <a href="https://n8n-prod.cadastra.com/webhook/clarity-cro-report" style="display:inline-block;background:#e84e1b;color:#ffffff;text-decoration:none;font-weight:700;font-size:13px;padding:10px 22px;border-radius:8px">Abrir dashboard completo</a>
    <div style="font-size:10px;color:#9ca3af;margin-top:12px">Gerado automaticamente via n8n · Microsoft Clarity Data Export API + Google Analytics 4</div>
  </td></tr>
</table>
</td></tr></table></body></html>`;

return [{ json: {
  emails: d.emails,
  subject: `📊 Resumo Semanal CRO/UX — ${d.projectName} · ${d.periodo?.de} a ${d.periodo?.ate}`,
  html
} }];
